from collections import defaultdict

def dfs_rec(n, edges, src=0):
    g = defaultdict(list)
    for u, v in edges:
        g[u].append(v)
        g[v].append(u)
    seen = [False] * n
    order = []

    def go(u):
        seen[u] = True
        order.append(u)
        for v in g[u]:
            if not seen[v]:
                go(v)

    go(src)
    return order
